const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), qi=v=>'`'+String(v).replace(/`/g,'``')+'`', lit=v=>v===null?'NULL':"'"+String(v).replace(/\\/g,'\\\\').replace(/'/g,"''")+"'";
let editorSchema=Object.create(null),editorValidationId=0;
let favorites=readStoredJSON('sql-favorites',[]);
let engine, database='',table='',view='home',databases=[],tables=[],columns=[],history=[],lastSQL='',notice='',filter='',sort='',desc=false,page=0,editing=null,version='',busy=false;
const content=$('#content');const icons={Databases:'▣',Structure:'▤',Browse:'▦',SQL:'▣',Search:'⌕',Insert:'＋',Export:'↗',Import:'↙',Operations:'⚙',Home:'⌂'};
