async function q(sql,params){return engine.query(sql,params)}
async function refresh(){databases=(await q('SHOW DATABASES')).map(x=>Object.values(x)[0]);if(database&&!databases.includes(database)){database='';table=''}tables=database?(await q('SHOW TABLE STATUS FROM '+qi(database))).map(x=>({name:x.Name,rows:x.Rows,engine:x.Engine,collation:x.Collation,size:Number(x.Data_length)+Number(x.Index_length)})):[];if(table&&!tables.some(t=>t.name===table))table='';columns=table?await q('SHOW COLUMNS FROM '+qi(table)+' FROM '+qi(database)):[];editorSchema=Object.create(null);if(database){for(const c of await q('SELECT TABLE_NAME,COLUMN_NAME,COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = ? ORDER BY TABLE_NAME,ORDINAL_POSITION',[database]))(editorSchema[c.TABLE_NAME]??=[]).push({name:c.COLUMN_NAME,type:c.COLUMN_TYPE})}await renderTree();document.querySelectorAll('#tree a:not([href])').forEach(a=>{a.href='#';a.setAttribute('role','button')})}
async function renderTree(){let html='<div class="db-row" style="padding-left:25px"><span class="tree-icon">'+ico('New database')+'</span><a data-action="newdb">New</a></div>';for(const db of databases){if(!db.toLowerCase().includes(filter)&&db!==database)continue;html+=`<div class="db-row"><button class="tree-toggle" data-db="${esc(db)}">${db===database?'−':'+'}</button><span class="tree-icon">${ico('Databases')}</span><a data-db="${esc(db)}">${esc(db)}</a></div>`;if(db===database){html+=`<div class="table-row">${ico('New table')}<a data-action="newtable">New</a></div>`;for(const t of tables){if(filter&&!t.name.toLowerCase().includes(filter)&&!db.toLowerCase().includes(filter))continue;html+=`<div class="table-row ${t.name===table?'active':''}"><button class="tree-toggle" data-table="${esc(t.name)}" data-target="structure">+</button><span class="tree-icon">${ico('Structure')}</span><a data-table="${esc(t.name)}">${esc(t.name)}</a></div>`}}}$('#tree').innerHTML=html}
function tabs(){let list=table?['Browse','Structure','SQL','Search','Insert','Export','Import','Privileges','Operations','Tracking','Triggers']:database?['Structure','SQL','Search','Query','Export','Import','Operations','Privileges','Routines','Events','Triggers','Tracking','Designer','Central columns']:['Databases','SQL','Status','User accounts','Export','Import','Settings','Replication','Variables','Charsets','Engines','Plug-ins'];$('#tabs').innerHTML=list.map(n=>`<button class="${view===n.toLowerCase()?'active':''}" data-view="${n.toLowerCase()}">${ico(n)}${n}</button>`).join('');$('#breadcrumb').innerHTML=`<button class="nav-toggle" data-action="toggle" aria-label="Toggle database navigation" title="Toggle database navigation">${document.body.classList.contains('collapsed')?'→':'←'}</button><a data-action="home">${ico('Server')}Server: browser</a>${database?' &nbsp;»&nbsp; <a data-db="'+esc(database)+'">'+ico('Databases')+'Database: '+esc(database)+'</a>':''}${table?' &nbsp;»&nbsp; <a data-table="'+esc(table)+'">'+ico('Browse')+'Table: '+esc(table)+'</a>':''}`;content.className='view-'+view.replaceAll(' ','-')}
function message(text,type=''){return `<div class="message ${type}" role="${type==='error'?'alert':'status'}">${type==='error'?ico('Help'):type==='info'?'':`<img class="icon" src="theme/img/s_success.png" alt="">`}${esc(text)}</div>`}function panel(title,body){return `<section class="panel"><h2>${title}</h2><div class="panel-body">${body}</div></section>`}function resultGrid(rows,fields){fields=fields||Object.keys(rows[0]||{});return `<div class="table-wrap"><table><thead><tr>${fields.map(c=>'<th>'+esc(c)+'</th>').join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+fields.map(c=>'<td>'+ (r[c]===null?'<i class="muted">NULL</i>':esc(r[c]))+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`}
async function render(){disposeSQLEditor();tabs();if(view==='home')home();else if(view==='databases')await dbList();else if(view==='structure'){await structure();const conflicts=columns.filter(c=>reservedWords.has(c.Field.toUpperCase()));if(conflicts.length)content.insertAdjacentHTML('afterbegin',message('Reserved column names: '+conflicts.map(c=>c.Field).join(', ')+'. Use backticks around these names in SQL.','info'));}else if(view==='browse')await browse();else if(view==='sql')sqlView();else if(view==='insert')insertView();else if(view==='search')searchView();else if(view==='export')exportView();else if(view==='import')importView();else if(view==='operations')operations();else await serverView();if(notice){content.insertAdjacentHTML('afterbegin',notice);notice=''}document.querySelectorAll('#content a[data-action]:not([href]),#content a[data-view]:not([href])').forEach(a=>{a.href='#';a.setAttribute('role','button')})}
function home(){content.innerHTML=`<div class="panels"><div>${panel('General settings',`<div class="home-fields"><div class="field"><label>${ico('Charsets')}Server connection collation: ${ico('Help')}</label><select id="connection-collation"><option>utf8mb4_unicode_ci</option><option>utf8mb4_general_ci</option></select></div><p><a data-view="settings">${ico('Settings')}More settings</a></p></div>`)}${panel('Appearance settings',`<div class="home-fields"><div class="field"><label>${ico('Language')}Language ${ico('Help')}</label><select class="language"><option>English (United Kingdom)</option></select></div><div class="field"><label>${ico('Theme')}Theme</label><select class="theme-choice"><option>pmahomme</option></select><button data-action="themes">View all</button></div></div>`)}</div><div>${panel('Database server',`<ul><li>Server: browser via WebAssembly</li><li>Server type: MariaDB</li><li>Server connection: local browser instance ${ico('Help')}</li><li>Server version: ${esc(version)}</li><li>Protocol version: embedded API</li><li>User: root (local practice)</li><li>Server charset: UTF-8 Unicode (utf8mb4)</li></ul>`)}${panel('Web server',`<ul><li>HTML, CSS and JavaScript</li><li>Database client: lite4mariadb 0.1.2</li><li>Database engine: WebAssembly with InnoDB</li><li>Storage: IndexedDB in this browser</li></ul>`)}${panel('phpMyAdmin',`<ul><li>UI reference: phpMyAdmin 5.2.1, pmahomme</li><li><a data-action="help">Documentation</a></li><li><a href="https://www.phpmyadmin.net/" target="_blank" rel="noopener">Official Homepage</a></li><li><a data-action="help">Workspace help</a></li><li><a data-action="example" data-example="join">Try a JOIN query</a></li><li><a data-view="export">Export your work</a></li><li><a href="PHPMYADMIN-LICENSE.txt" target="_blank">Licence</a></li></ul>`)}</div></div><div class="message info helper-info">This independent learning workspace saves databases in this browser. Export your work before leaving a public computer.</div>`}
async function dbList(){content.innerHTML=`<h1>Databases</h1><fieldset><legend>Create database</legend><form id="create-db"><input name="name" required placeholder="Database name" pattern="[a-zA-Z_][a-zA-Z0-9_]*" aria-label="Database name"> <select name="collation"><option>utf8mb4_unicode_ci</option><option>utf8mb4_general_ci</option></select> <button>Create</button></form></fieldset><div class="table-wrap"><table><thead><tr><th>Database</th><th>Collation</th><th>Action</th></tr></thead><tbody>${databases.map(d=>`<tr><td><a data-db="${esc(d)}">▣ ${esc(d)}</a></td><td>utf8mb4_unicode_ci</td><td>${!['mysql','information_schema','performance_schema','sys'].includes(d)?`<a class="danger" data-action="dropdb" data-name="${esc(d)}">⊗ Drop</a>`:'<span class="muted">System database</span>'}</td></tr>`).join('')}</tbody></table></div><p>${databases.length} databases</p>`}
async function structure(){if(!database){view='databases';return render()}if(table){const indexes=await q('SHOW INDEX FROM '+qi(table));content.innerHTML=resultGrid(columns.map((c,i)=>({'#':i+1,Name:c.Field,Type:c.Type,Collation:'',Null:c.Null,Default:c.Default,Extra:c.Extra,Action:'SQL'})))+`<div class="toolbar"><a data-view="insert">${ico('Insert')}Insert row</a><a data-view="sql">${ico('Edit')}Edit structure with SQL</a></div><fieldset><legend>Indexes</legend>${resultGrid(indexes,['Key_name','Non_unique','Column_name','Index_type'])}</fieldset>`;return}content.innerHTML=`<fieldset class="table-filter"><legend>Filters</legend><label>Containing the word: &nbsp; <input id="structure-filter" aria-label="Filter tables"></label></fieldset><div class="table-wrap"><table id="structure-table"><thead><tr><th></th><th>Table &nbsp; ▴</th><th colspan="2">Action</th><th>Rows ${ico('Help')}</th><th>Type</th><th>Collation</th><th>Size</th><th>Overhead</th></tr></thead><tbody>${tables.map(t=>`<tr><td><input type="checkbox" class="table-check" value="${esc(t.name)}" aria-label="Select ${esc(t.name)}"></td><td><a data-table="${esc(t.name)}"><b>${esc(t.name)}</b></a></td><td><a data-favtable="${esc(t.name)}">${ico('Favorite')}</a></td><td>${['Browse','Structure','Search','Insert'].map(v=>`<a class="link" data-table="${esc(t.name)}" data-target="${v.toLowerCase()}">${ico(v)}${v}</a>`).join(' ')}<a class="link" data-tableop="empty" data-name="${esc(t.name)}">${ico('Empty')}Empty</a> <a class="link" data-tableop="drop" data-name="${esc(t.name)}">${ico('Delete')}Drop</a></td><td class="num">${esc(t.rows)}</td><td>${esc(t.engine)}</td><td>${esc(t.collation)}</td><td style="font-family:monospace">${(t.size/1024).toFixed(1)} KiB</td><td class="num">-</td></tr>`).join('')}</tbody><tfoot><tr><td></td><td><b>${tables.length} tables</b></td><td></td><td><b>Sum</b></td><td class="num"><b>${tables.reduce((n,t)=>n+Number(t.rows),0)}</b></td><td>InnoDB</td><td></td><td>${(tables.reduce((n,t)=>n+t.size,0)/1024).toFixed(1)} KiB</td><td>0 B</td></tr></tfoot></table></div><div class="bulk">↳ <label><input type="checkbox" data-check-all="table-check">Check all</label><select id="table-bulk"><option value="">With selected:</option><option value="export">Export</option><option value="empty">Empty</option><option value="drop">Drop</option></select></div><hr><div class="toolbar"><a data-action="print">${ico('Print')}Print</a><a data-action="dictionary">${ico('Designer')}Data dictionary</a></div><fieldset><legend>${ico('New table')}Create new table</legend><form id="new-table"><div class="field"><div><label>Table name</label><br><input name="name" required aria-label="Table name" style="width:178px;margin-top:9px"></div><div><label>Number of columns</label><br><input name="count" type="number" min="1" max="30" value="4" style="width:178px;margin-top:9px"></div><button style="align-self:flex-end">Create</button></div></form></fieldset>`}
let browseRows=[];let activeWhere='',activeParams=[];
async function browse(where=activeWhere,params=activeParams){activeWhere=where;activeParams=params;if(!table){view='structure';return render()}const count=await q('SELECT COUNT(*) AS n FROM '+qi(table)+(where?' WHERE '+where:''),params);const query='SELECT * FROM '+qi(table)+(where?' WHERE '+where:'')+(sort?' ORDER BY '+qi(sort)+(desc?' DESC':' ASC'):'')+' LIMIT '+rowLimit+' OFFSET '+page*rowLimit;browseRows=await q(query,params);let tools=`<div class="row-tools"><label><input id="show-all-rows" type="checkbox">Show all</label><span style="border-left:1px solid #999;padding-left:12px">Number of rows:</span><select id="browse-limit">${[25,50,100,250].map(n=>`<option ${rowLimit===n?'selected':''}>${n}</option>`).join('')}</select><label>Filter rows:</label><input id="browse-filter" placeholder="Search this table"><label>Sort by key:</label><select id="browse-sort"><option value="">None</option>${columns.map(c=>`<option value="${esc(c.Field)}" ${sort===c.Field?'selected':''}>${esc(c.Field)}</option>`).join('')}</select></div>`;content.innerHTML=message(`Showing rows ${browseRows.length?page*rowLimit:0} - ${browseRows.length?page*rowLimit+browseRows.length-1:0} (${count[0].n} total, Query executed on local MariaDB.)`)+`<pre class="query">${esc('SELECT * FROM '+qi(table)+(where?' WHERE '+where:''))}</pre><div class="profiling"><label><input type="checkbox">Profiling</label> [ <a data-action="edit-query">Edit inline</a> ] [ <a data-action="edit-query">Edit</a> ] [ <a data-action="explain-query">Explain SQL</a> ] [ <a data-action="php-code">Create PHP code</a> ] [ <a data-action="refresh">Refresh</a> ]</div>${tools}<button data-action="extra-options" style="border-radius:3px;font-size:11px;padding:2px 8px">Extra options</button><div class="table-wrap" style="margin-top:16px"><table id="browse-table"><thead><tr><th colspan="2">←T→</th>${columns.map(c=>`<th><a data-sort="${esc(c.Field)}">${esc(c.Field)} ${sort===c.Field?(desc?'▼':'▲'):''}</a></th>`).join('')}</tr></thead><tbody>${browseRows.map((r,i)=>`<tr><td><input type="checkbox" class="row-check" value="${i}" aria-label="Select row ${i+1}"></td><td><a class="link" data-action="editrow" data-index="${i}">${ico('Edit')}Edit</a><a class="link" data-action="copyrow" data-index="${i}">${ico('Copy')}Copy</a><a class="link" data-action="deleterow" data-index="${i}">${ico('Delete')}Delete</a></td>${columns.map(c=>'<td>'+(r[c.Field]===null?'<i class="muted">NULL</i>':esc(r[c.Field]))+'</td>').join('')}</tr>`).join('')}</tbody></table></div>${browseRows.length?'':'<div class="empty">This table has no rows matching your query.</div>'}<div class="bulk">↳ <label><input type="checkbox" data-check-all="row-check">Check all</label><i>With selected:</i><a data-action="bulk-delete">${ico('Delete')}Delete</a><a data-action="bulk-copy">${ico('Copy')}Copy</a><a data-view="export">${ico('Export')}Export</a></div><div class="toolbar"><button data-action="previous" ${page===0?'disabled':''}>‹ Previous</button><span>Page ${page+1}</span><button data-action="next" ${(page+1)*rowLimit>=count[0].n?'disabled':''}>Next ›</button></div><fieldset><legend>Query results operations</legend><div class="toolbar"><a data-action="print">${ico('Print')}Print</a><button data-action="copy-results">${ico('Copy')}Copy to clipboard</button><button data-view="export">${ico('Export')}Export</button><button data-action="create-view">${ico('Browse')}Create view</button></div></fieldset>`}
function sqlView(){disposeSQLEditor();content.innerHTML=`<fieldset class="sql-area"><legend>Run SQL query/queries on ${table?'table “'+esc(table)+'”':database?'database “'+esc(database)+'”':'server “browser”'}: ${ico('Help')}</legend><div class="sql-box"><textarea id="sql-editor" spellcheck="false" aria-label="SQL query">${esc(lastSQL||(table?'SELECT * FROM '+qi(table)+' WHERE 1;':''))}</textarea></div><p class="editor-shortcuts">Ctrl+Space: suggestions · Enter / Tab: insert suggestion · Ctrl+Enter: run query</p><div class="query-buttons"><button data-action="clear-sql">Clear</button><button data-action="format-sql">Format</button><button data-action="restore-sql">Get auto-saved query</button></div><p class="query-meta"><label><input id="bind-params" type="checkbox">Bind parameters</label> ${ico('Help')}<input id="parameter-values" placeholder='JSON values: [1, "name"]' aria-label="Parameter values" hidden></p><p class="query-meta">Bookmark this SQL query: <input id="bookmark-name" type="text" aria-label="Bookmark name"></p><div class="sql-options"><label>Delimiter <input id="sql-delimiter" type="text" value=";"></label><label><input id="show-query" type="checkbox">Show this query here again</label><label><input id="retain-query" type="checkbox" ${localStorage.getItem('retain-query')==='true'?'checked':''}>Retain query box</label><label><input id="rollback-query" type="checkbox">Rollback when finished</label><label><input id="foreign-keys" type="checkbox" checked>Enable foreign key checks</label><button data-action="run" title="Ctrl + Enter">Go</button></div></fieldset>${table?`<div class="toolbar query-buttons">${['SELECT *','INSERT','UPDATE','DELETE'].map(x=>`<button data-template="${x}">${x}</button>`).join('')}</div>`:''}<div id="sql-results"></div>`;mountSQLEditor($('#sql-editor'),{schema:editorSchema,defaultTable:table,validate:validateEditorSQL,onRun:()=>executeEditor().catch(err=>{$('#sql-results').innerHTML=message(err.message,'error')})});updateLines()}
function updateLines(){let e=$('#sql-editor');if(e&&$('#line-numbers'))$('#line-numbers').innerHTML=Array.from({length:e.value.split('\n').length},(_,i)=>i+1).join('<br>')}
async function runSQL(sql){if(busy)return;busy=true;const start=performance.now();lastSQL=sql;let results;try{results=await engine.execMulti(sql);history.unshift({sql,ok:true,time:new Date().toLocaleTimeString()});let current=await q('SELECT DATABASE() AS db');database=current[0].db||'';await refresh();await persist();view='sql';sqlView();tabs();$('#sql-results').innerHTML=results.map(r=>message(r.fields?`Query returned ${r.rows.length} row(s). (${((performance.now()-start)/1000).toFixed(3)} seconds)`:`Query executed successfully. ${r.affected||0} row(s) affected.`)+(r.fields?resultGrid(r.rows,r.fields):'')).join('');}catch(e){history.unshift({sql,ok:false,time:new Date().toLocaleTimeString()});if($('#sql-results'))$('#sql-results').innerHTML=message('MariaDB said: '+e.message,'error');else{notice=message(e.message,'error');await render()}await refresh();await persist()}finally{busy=false;renderHistory()}}
function insertView(){if(!table){view='structure';render();return}content.innerHTML=`<form id="insert-row"><div class="table-wrap"><table class="insert-table"><thead><tr><th>Column</th><th>Type</th><th>Function</th><th>Null</th><th>Value</th></tr></thead><tbody>${columns.map((c,i)=>`<tr><td>${esc(c.Field)}</td><td>${esc(c.Type)}</td><td><select name="fn-${i}" aria-label="Function for ${esc(c.Field)}"><option></option>${['NOW','CURRENT_DATE','UUID','UPPER','LOWER','MD5','SHA1'].map(fn=>'<option>'+fn+'</option>').join('')}</select></td><td><input name="null-${i}" type="checkbox" ${editing?editing[c.Field]===null?'checked':'':c.Null==='YES'||c.Extra.includes('auto_increment')?'checked':''} aria-label="${esc(c.Field)} is NULL"></td><td><input name="col-${i}" value="${esc(editing?editing[c.Field]:c.Default??'')}" placeholder="${c.Extra.includes('auto_increment')?'':c.Default!==null?'Default: '+esc(c.Default):''}" aria-label="${esc(c.Field)} value"></td></tr>`).join('')}</tbody></table></div><div style="width:min(904px,100%);text-align:right"><button>Go</button></div><div class="insert-controls"><select id="insert-mode"><option>${editing?'Save':'Insert as new row'}</option></select> <b style="margin:0 10px">and then</b> <select id="after-insert"><option value="browse">Go back to previous page</option><option value="insert">Insert another new row</option></select><div style="margin-top:8px;margin-left:287px"><button type="button" data-action="preview-insert">Preview SQL</button> <button type="reset">Reset</button> <button>Go</button></div></div></form>`}
function searchView(){if(!table){content.innerHTML='<h1>Search</h1><p>Select a table to search its columns.</p>'+tables.map(t=>`<p><a data-table="${esc(t.name)}" data-target="search">▦ ${esc(t.name)}</a></p>`).join('');return}content.innerHTML=`<h1>Search table ${esc(table)}</h1><form id="search-table"><div class="table-wrap"><table class="insert-table"><thead><tr><th>Column</th><th>Type</th><th>Operator</th><th>Value</th></tr></thead><tbody>${columns.map((c,i)=>`<tr><td>${esc(c.Field)}</td><td>${esc(c.Type)}</td><td><select name="op-${i}">${['=','!=','>','>=','<','<=','LIKE','IS NULL','IS NOT NULL'].map(o=>`<option>${esc(o)}</option>`).join('')}</select></td><td><input name="val-${i}" aria-label="Search ${esc(c.Field)}" placeholder="Leave blank to ignore"></td></tr>`).join('')}</tbody></table></div><p class="muted">Conditions are joined with AND. For LIKE, use % as a wildcard.</p><div class="sql-bottom"><button>Go</button></div></form>`}
function exportView(){content.innerHTML=`<div class="transfer"><h1>Exporting ${table?'table “'+esc(table)+'”':database?'tables from the database “'+esc(database)+'”':'databases from the current server'}</h1><fieldset><legend>Export templates:</legend><div class="template-grid"><div><h3>New template:</h3><div class="field"><label>Template name</label><input id="export-template-name" placeholder="Template name"><button data-action="save-template">Create</button></div></div><div><h3>Existing templates:</h3><div class="field"><label>Template:</label><select id="export-template">${exportTemplateOptions()}</select><button data-action="update-template">Update</button><button data-action="delete-template">Delete</button></div></div></div></fieldset><fieldset><legend>Export method:</legend><label><input type="radio" name="export-method" value="quick" checked>Quick - display only the minimal options</label><label><input type="radio" name="export-method" value="custom">Custom - display all possible options</label><div id="custom-export" hidden><p style="margin-top:15px">Output:</p><label><input id="export-structure" type="checkbox" checked>Structure</label><label><input id="export-data" type="checkbox" checked>Data</label><label><input id="export-drop" type="checkbox" checked>Add DROP TABLE statement</label></div></fieldset><fieldset><legend>Format:</legend><select id="export-format"><option value="sql">SQL</option><option value="csv" ${!table?'disabled':''}>CSV</option></select></fieldset><button data-action="download">Export</button></div>`}
function importView(){content.innerHTML=`<div class="transfer"><h1>Importing into ${database?'the database “'+esc(database)+'”':'the current server'}</h1><form id="import-sql"><fieldset><legend>File to import:</legend><p>File may be compressed (gzip) or uncompressed.<br>A compressed file's name must end in .[format].[compression]. Example: .sql.gz</p><p style="margin-top:19px;margin-bottom:8px">Browse your computer: <small>(Max: 40MiB)</small></p><input id="import-file" type="file" accept=".sql,.txt,.gz" required><p style="margin:16px 0">You may also drag and drop a file on any page.</p><p>Character set of the file:</p><select id="import-charset"><option value="utf-8">utf-8</option><option value="windows-1252">windows-1252</option></select></fieldset><fieldset><legend>Partial import:</legend><label><input id="partial-import" type="checkbox" class="switch" checked>Allow the interruption of an import when canceled.</label><p class="muted" style="margin:4px 0 16px 32px">The current statement finishes before cancellation. Earlier statements may remain applied.</p><p>Skip this number of queries (for SQL) starting from the first one:</p><input id="import-skip" type="number" min="0" value="0"></fieldset><fieldset><legend>Other options</legend><p>Target database (optional for dumps that create/select their own database):</p><input id="import-target" type="text" value="${esc(database)}" placeholder="e.g. university_db" aria-label="Import target database"><p class="muted">A new database will be created if this name does not exist. Leave blank to use the SQL file’s database commands, or its filename for table-only files.</p><label><input id="import-continue" type="checkbox" class="switch" checked>Continue after SQL errors and report failed statements</label><label><input id="import-fk" type="checkbox" class="switch" checked>Enable foreign key checks</label></fieldset><fieldset><legend>Format</legend><select><option>SQL</option></select></fieldset><fieldset><legend>Format-specific options:</legend><p>SQL dialect / legacy compatibility:</p><select id="import-compat"><option value="auto">Auto-detect (MySQL/MariaDB or labelled SQLite learning file)</option><option value="mysql">MySQL / MariaDB — unchanged syntax</option><option value="sqlite">SQLite learning-file compatibility (backslashes and ||)</option></select><p class="muted">Warnings are reported without stopping the import. Unsupported SQL is reported as an error; successful statements remain applied.</p><p>SQL compatibility mode:</p><select id="import-mode"><option>NONE</option><option>ANSI</option><option>MYSQL40</option></select><label style="margin-top:12px"><input id="import-zero" type="checkbox" class="switch" checked>Do not use AUTO_INCREMENT for zero values</label></fieldset><button>Import</button></form><div id="import-progress"></div></div>`}
function operations(){content.innerHTML=`<h1>Operations</h1>${table?panel('Table maintenance',`<p><a data-action="checktable">Check table</a></p><p><a data-action="emptytable" class="danger">Empty the table (TRUNCATE)</a></p><p><a data-action="droptable" class="danger">Delete the table (DROP)</a></p>`):panel('Remove database',`<p><a data-action="dropdb" data-name="${esc(database)}" class="danger">Drop the database (DROP)</a></p>`)}${panel('Browser storage',`<p>Your work is saved on this browser. Other devices do not share it.</p><button data-action="persist">Save now</button> <button data-view="export">Export backup</button>`)}`}
async function persist(){try{await engine.persist();$('#save-status').textContent=getStorageIssue()||'Saved in this browser · '+new Date().toLocaleTimeString()}catch(e){$('#save-status').textContent='Save failed — export your work';notice=message('Unable to save: '+e.message,'error');$('#save-status').setAttribute('role','alert')}}
function renderHistory(){$('#history').innerHTML=history.slice(0,80).map((h,i)=>`<div><span class="${h.ok?'':'danger'}">${h.ok?'✓':'✕'} ${esc(h.time)}</span> <a data-action="star" data-index="${i}" title="Save favorite">☆</a> <a data-history="${i}">${esc(h.sql)}</a></div>`).join('')||'<div>No queries yet.</div>'}
function dialog(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#dialog').showModal()}
function help(){dialog('About this SQL workspace',`<div class="help"><p>This app recreates the familiar phpMyAdmin pmahomme layout for learning. It runs <b>real MariaDB ${esc(version)}</b> in WebAssembly, rather than simulating SQL.</p><p>Use Browse, Structure, SQL, Search, Insert, Import, Export and Operations. Create databases and tables, edit rows, run joins and transactions.</p><p>It is <b>not the complete phpMyAdmin application</b>. Server user administration, replication, PHP configuration, visual relationship diagrams and advanced admin screens are not included. MariaDB and MySQL have version-specific differences.</p><p>Data is stored in this browser's IndexedDB. Use one tab at a time. Public computers, private browsing and cleared browser storage can lose your data. Export SQL before leaving.</p><p>The engine requires a browser with WebAssembly threads and cross-origin isolation. First load is around 17 MB.</p><p>Try: <code>SHOW DATABASES;</code>, <code>DESCRIBE students;</code>, <code>SELECT * FROM students;</code>.</p><p><a href="SOURCE.txt" target="_blank">Licenses and source attribution</a></p></div>`)}
function download(text,name,type='text/plain'){let url=URL.createObjectURL(new Blob([text],{type}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
async function exportSQL(){if($('#export-format').value==='csv'&&table){let rows=await q('SELECT * FROM '+qi(table));let cs=columns.map(c=>c.Field),cv=v=>'"'+String(v??'').replace(/"/g,'""')+'"';download([cs.map(cv).join(','),...rows.map(r=>cs.map(c=>cv(r[c])).join(','))].join('\r\n'),table+'.csv','text/csv');return}let dbs=database?[database]:databases.filter(d=>!['mysql','sys','performance_schema','information_schema'].includes(d));let sql='-- OurSQL export\n-- MariaDB '+version+'\nSET FOREIGN_KEY_CHECKS=0;\n';for(const d of dbs){sql+='CREATE DATABASE IF NOT EXISTS '+qi(d)+';\nUSE '+qi(d)+';\n';let ts=table?[table]:(await q('SHOW TABLES FROM '+qi(d))).map(r=>Object.values(r)[0]);for(const t of ts){let create=await q('SHOW CREATE TABLE '+qi(d)+'.'+qi(t));if($('#export-structure').checked)sql+='\n'+($('#export-drop').checked?'DROP TABLE IF EXISTS '+qi(t)+';\n':'')+Object.values(create[0])[1]+';\n';let rows=await q('SELECT * FROM '+qi(d)+'.'+qi(t));if($('#export-data').checked)for(const r of rows){sql+='INSERT INTO '+qi(t)+' ('+Object.keys(r).map(qi).join(',')+') VALUES ('+Object.values(r).map(lit).join(',')+');\n'}}}sql+='SET FOREIGN_KEY_CHECKS=1;\n';download(sql,(table||database||'databases')+'.sql')}
function rowWhere(r){let keys=columns.filter(c=>c.Key==='PRI');if(!keys.length)throw Error('Row editing/deletion requires a primary key. Add one in SQL first.');return {sql:keys.map(c=>qi(c.Field)+' <=> ?').join(' AND '),params:keys.map(c=>r[c.Field])}}
async function action(a,el){switch(a){case'home':database='';table='';view='home';await refresh();await render();break;case'refresh':await refresh();await render();break;case'help':help();break;case'toggle':if(globalThis.matchMedia?.('(max-width:600px)').matches)document.body.classList.toggle('nav-open');else document.body.classList.toggle('collapsed');break;case'recent':dialog('Recent SQL queries',history.slice(0,10).map(h=>'<pre class="query">'+esc(h.sql)+'</pre>').join('')||'No queries yet.');break;case'favorites':dialog('Favorite queries',favorites.map((sql,i)=>'<p><a data-favorite="'+i+'">'+esc(sql)+'</a></p>').join('')||'Star a query in the Console to save it here.');break;case"star":{let sql=history[Number(el.dataset.index)].sql;if(!favorites.includes(sql))favorites.push(sql);localStorage.setItem('sql-favorites',JSON.stringify(favorites));renderHistory();break;}case'newdb':database='';table='';view='databases';await render();$('#create-db input').focus();break;case'newtable':table='';view='structure';await render();$('#new-table input').focus();break;case'run':await executeEditor();break;case'clear-sql':$('#sql-editor').value='';updateLines();break;case'console':$('#console-panel').hidden=!$('#console-panel').hidden;renderHistory();break;case'previous':page=Math.max(0,page-1);await browse();break;case'next':page++;await browse();break;case'persist':await persist();notice=message('Database saved in this browser.');await render();break;case'download':await exportSQL();break;case'editrow':editing=browseRows[Number(el.dataset.index)];rowWhere(editing);view='insert';await render();break;case'deleterow':{let r=browseRows[Number(el.dataset.index)],w=rowWhere(r);if(!confirm('Delete this row? This cannot be undone.'))return;await engine.exec('DELETE FROM '+qi(table)+' WHERE '+w.sql+' LIMIT 1',w.params);await persist();await browse();break}case'dropdb':if(['mysql','sys','information_schema','performance_schema'].includes(el.dataset.name))throw Error('System databases cannot be dropped here.');if(!confirm('Drop database '+el.dataset.name+' and all its data?'))return;await engine.exec('DROP DATABASE '+qi(el.dataset.name));database='';table='';view='databases';await refresh();await persist();await render();break;case'emptytable':if(!confirm('Empty '+table+'? All rows will be permanently removed.'))return;await engine.exec('TRUNCATE TABLE '+qi(table));await persist();notice=message('Table emptied.');await render();break;case'droptable':if(!confirm('Drop table '+table+'?'))return;await engine.exec('DROP TABLE '+qi(table));table='';view='structure';await refresh();await persist();await render();break;case'checktable':notice=message(JSON.stringify(await q('CHECK TABLE '+qi(table))));await render();break;case'example':if(!databases.includes('school'))throw Error('The school example database is missing. Create or import it first.');database='school';table='';await engine.exec('USE school');await refresh();view='sql';lastSQL=el.dataset.example==='join'?`SELECT s.name, c.title, e.grade\nFROM students AS s\nJOIN enrollments AS e ON s.id = e.student_id\nJOIN courses AS c ON c.id = e.course_id\nORDER BY s.name;`:`SELECT department, COUNT(*) AS total_students,\n       ROUND(AVG(age), 1) AS average_age\nFROM students\nGROUP BY department\nORDER BY total_students DESC;`;await render();break}}
document.addEventListener('click',async e=>{let el=e.target.closest('[data-action],[data-view],[data-db],[data-table],[data-sort],[data-template],[data-history],[data-favorite]');if(!el||!engine)return;e.preventDefault();if(busy&&el.dataset.action!=='cancel-import')return;try{if(el.dataset.db){if(busy) return;database=el.dataset.db;table='';page=0;await engine.exec('USE '+qi(database));view='structure';await refresh();await render()}else if(el.dataset.table){if(busy) return;table=el.dataset.table;page=0;sort='';editing=null;activeWhere='';activeParams=[];view=el.dataset.target||'browse';await refresh();await render()}else if(el.dataset.view){if(busy) return;view=el.dataset.view;editing=null;await render()}else if(el.dataset.sort){desc=sort===el.dataset.sort?!desc:false;sort=el.dataset.sort;await browse()}else if(el.dataset.template){if(!table)throw Error('Select a table first.');let names=columns.filter(c=>!c.Extra.includes('auto_increment')).map(c=>qi(c.Field));$('#sql-editor').value={'SELECT *':'SELECT * FROM '+qi(table)+' WHERE 1;','INSERT':'INSERT INTO '+qi(table)+' ('+names.join(', ')+")\nVALUES ("+names.map(()=>"'value'").join(', ')+');','UPDATE':'UPDATE '+qi(table)+' SET '+names[0]+" = 'value'\nWHERE "+qi(columns[0].Field)+' = 1;','DELETE':'DELETE FROM '+qi(table)+' WHERE '+qi(columns[0].Field)+' = 1;'}[el.dataset.template];updateLines()}else if(el.dataset.favorite!==undefined){lastSQL=favorites[Number(el.dataset.favorite)];view='sql';await render();$('#dialog').close()}else if(el.dataset.history!==undefined){lastSQL=history[Number(el.dataset.history)].sql;view='sql';await render();$('#console-panel').hidden=true}else if(!await extraAction(el.dataset.action,el))await action(el.dataset.action,el)}catch(err){notice=message(err.message,'error');await render()}});
document.addEventListener('input',e=>{if(e.target.id==='sql-editor')updateLines();if(e.target.id==='tree-filter'){filter=e.target.value.toLowerCase();renderTree()}if(e.target.id==='font-size')document.body.style.fontSize=e.target.value});document.addEventListener('keydown',e=>{if(!e.defaultPrevented&&(e.ctrlKey||e.metaKey)&&e.key==='Enter'&&$('#sql-editor')){e.preventDefault();executeEditor()}});
document.addEventListener('submit',async e=>{if(e.target.closest('dialog'))return;e.preventDefault();let f=e.target,fd=new FormData(f);try{if(await extraSubmit(f,fd)){return}else if(f.id==='create-db'){database=fd.get('name');await engine.exec('CREATE DATABASE '+qi(database)+' COLLATE '+fd.get('collation'));await engine.exec('USE '+qi(database));table='';view='structure'}else if(f.id==='new-table'){pendingTable={name:fd.get('name'),count:Number(fd.get('count'))};createTableView();return}else if(f.id==='insert-row'){await saveInsert(fd);return}else if(f.id==='search-table'){let conditions=[],params=[];columns.forEach((c,i)=>{let op=fd.get('op-'+i),v=fd.get('val-'+i);if(op.startsWith('IS '))conditions.push(qi(c.Field)+' '+op);else if(v!==''){conditions.push(qi(c.Field)+' '+op+' ?');params.push(v)}});page=0;await browse(conditions.join(' AND '),params);return}else if(f.id==='import-sql'){await importFile();return}await refresh();await persist();await render()}catch(err){notice=message(err.message,'error');await render()}});
async function start(){document.body.dataset.engineState='loading';content.setAttribute('aria-busy','true');const loadingTimer=setTimeout(()=>{if(document.body.dataset.engineState==='loading')content.innerHTML=message('Still starting MariaDB. The first load may take longer on a slow connection.','info')+'<div class="startup-progress" aria-hidden="true"></div>'},8000);try{if(!crossOriginIsolated)throw Error('Database engine needs cross-origin isolation. Hosting must send COOP and COEP headers.');engine=await Lite4MariaDBWorker.create({dataDir:'idb://phpmyadmin-practice-v1'});version=(await q('SELECT VERSION() AS v'))[0].v;await refresh();if(!databases.includes('school')&&!localStorage.getItem('sql-practice-initialized')){await engine.execMulti(seed);localStorage.setItem('sql-practice-initialized','1');await persist();await refresh()}database='';table='';$('#engine-status').textContent='MariaDB '+version+' · local';await render();await persist()}catch(err){content.innerHTML=message('Could not start MariaDB: '+err.message,'error')+'<p>Use a current Chrome, Edge or Firefox browser. The app requires WebAssembly threads. No simulated SQL fallback is used.</p><button onclick="location.reload()">Retry</button>';$('#engine-status').textContent='Database unavailable';$('#save-status').textContent='Database unavailable';document.body.dataset.engineState='failed'}finally{clearTimeout(loadingTimer);content.setAttribute('aria-busy','false');if(document.body.dataset.engineState!=='failed')document.body.dataset.engineState='ready';if(getStorageIssue())$('#save-status').textContent=getStorageIssue()}}


const iconNames={'Databases':'s_db','Server':'s_host','SQL':'b_sql','Status':'s_status','User accounts':'s_rights','Export':'b_export','Import':'b_import','Settings':'b_props','Replication':'s_replication','Variables':'s_vars','Charsets':'s_asci','Engines':'b_engine','Plug-ins':'b_plugin','Browse':'b_browse','Structure':'b_props','Search':'b_search','Query':'s_db','Insert':'b_insrow','Privileges':'s_rights','Operations':'b_props','Routines':'b_routines','Events':'b_events','Triggers':'b_triggers','Tracking':'eye','Designer':'b_relations','Central columns':'centralColumns','Help':'b_help','Language':'s_lang','Theme':'s_theme','Edit':'b_edit','Copy':'b_insrow','Delete':'b_drop','Empty':'b_empty','New database':'b_newdb','New table':'b_table_add','Favorite':'b_favorite','Print':'b_print'};
function ico(n){return '<img class="icon" src="theme/img/'+(iconNames[n]||'b_info')+'.png" alt="">'}
function subTabs(names,selected){return '<div class="subtabs">'+names.map(n=>`<button data-sub="${esc(n)}" class="${selected===n?'active':''}">${esc(n)}</button>`).join('')+'</div>'}
let sub='';
async function serverView(){if(view==='status'){await statusView();return}if(view==='variables'){const rows=await q('SHOW GLOBAL VARIABLES');content.innerHTML='<h1>Server variables and settings '+ico('Help')+'</h1><fieldset><legend>Filters</legend><label>Containing the word: &nbsp; <input id="data-filter" aria-label="Filter variables"></label></fieldset><div class="table-wrap">'+variableGrid(rows)+'</div>';return}if(view==='engines'){const rows=await q('SHOW ENGINES');content.innerHTML='<h1>Storage engines</h1>'+resultGrid(rows.map(r=>({'Storage Engine':r.Engine,Description:r.Comment,Support:r.Support})),['Storage Engine','Description','Support']);return}if(view==='plug-ins'){const rows=await q('SHOW PLUGINS');const types=[...new Set(rows.map(r=>r.Type))];content.innerHTML='<h1>Plug-ins</h1><fieldset>'+types.map(t=>`<button data-plugin-type="${esc(t)}">${esc(t)}</button>`).join(' ')+'</fieldset>'+types.map(t=>`<section class="plugin-group" data-kind="${esc(t)}"><h3 style="background:#d3dce3;text-align:center;font-size:13px;padding:3px;max-width:1000px">${esc(t)}</h3>${resultGrid(rows.filter(r=>r.Type===t).map(r=>({'Plug-in':r.Name,Status:r.Status,Library:r.Library,Licence:r.License})))}</section>`).join('');return}if(view==='charsets'){const sets=(await q('SHOW CHARACTER SET')).sort((a,b)=>a.Charset.localeCompare(b.Charset)),coll=await q('SHOW COLLATION');content.innerHTML='<h1>Character sets and collations</h1>'+sets.map(cs=>`<fieldset><legend><b>${esc(cs.Charset)}</b><br>${esc(cs.Description)}</legend>${coll.filter(c=>c.Charset===cs.Charset).map(c=>`<div style="border-bottom:1px solid #ccc;padding:6px 0"><b>${esc(c.Collation)}</b>${c.Default==='Yes'?'<span class="badge" style="float:right">default</span>':''}<br>${esc(cs.Description)}, ${c.Collation.endsWith('_bin')?'binary':'case-insensitive'}</div>`).join('')}</fieldset>`).join('');return}if(view==='settings'){settingsView();return}if(view==='replication'){content.innerHTML='<h1>Replication</h1><fieldset><legend>Primary replication</legend>This browser instance is not configured as primary in a replication process.</fieldset><fieldset><legend>Replica replication</legend>This browser instance is not configured as replica in a replication process.</fieldset><p class="muted" style="margin:15px">Network replication is unavailable in the embedded browser engine.</p>';return}if(view==='user accounts'||view==='privileges'){await usersView();return}if(['routines','events','triggers'].includes(view)){let sql=view==='routines'?'SHOW PROCEDURE STATUS WHERE Db = '+lit(database):view==='events'?'SHOW EVENTS FROM '+qi(database):'SHOW TRIGGERS FROM '+qi(database);const rows=await q(sql);content.innerHTML='<h1>'+view[0].toUpperCase()+view.slice(1)+'</h1>'+resultGrid(rows)+(rows.length?'':'<p>No '+esc(view)+' found.</p>')+'<fieldset><legend>New</legend><a data-action="advanced-sql">'+ico('SQL')+'Create using SQL</a></fieldset>';return}if(view==='query'){view='sql';sqlView();tabs();return}content.innerHTML='<h1>'+esc(view[0].toUpperCase()+view.slice(1))+'</h1>'+message('This administration feature is not implemented in the local learning workspace.','info')+'<p><a data-view="sql">Open SQL</a></p>'}
function variableGrid(rows){return '<table class="compact-table" id="filterable-table"><thead><tr><th>Action</th><th>Variable</th><th style="text-align:right">Value</th></tr></thead><tbody>'+rows.map(r=>`<tr><td><a data-variable="${esc(r.Variable_name)}">${ico('Edit')}Edit</a></td><td><a data-variable="${esc(r.Variable_name)}">${esc(r.Variable_name.replaceAll('_',' '))}</a> ${ico('Help')}</td><td>${esc(r.Value)}</td></tr>`).join('')+'</tbody></table>'}
async function statusView(){const names=['Server','Processes','Query statistics','All status variables','Monitor','Advisor'];if(!names.includes(sub))sub='Server';const rows=await q('SHOW GLOBAL STATUS');let lookup=Object.fromEntries(rows.map(r=>[r.Variable_name,r.Value]));content.innerHTML=subTabs(names,sub);if(sub==='Processes'){content.innerHTML+=resultGrid(await q('SHOW PROCESSLIST'));return}if(sub==='All status variables'){content.innerHTML+='<h3>All status variables</h3><input id="data-filter" placeholder="Containing the word">'+resultGrid(rows);$('#content table').id='filterable-table';return}if(sub==='Query statistics'){content.innerHTML+='<h3>Query statistics</h3>'+resultGrid(rows.filter(r=>r.Variable_name.startsWith('Com_')),['Variable_name','Value']);return}if(sub==='Advisor'){content.innerHTML+='<fieldset><legend>Advisor</legend>Performance recommendations require a dedicated server workload. This engine is local to your browser.</fieldset>';return}const received=Number(lookup.Bytes_received||0),sent=Number(lookup.Bytes_sent||0);content.innerHTML+=`<h3 style="margin-left:10px">Network traffic since startup: ${((received+sent)/1024).toFixed(1)} KiB</h3><p style="margin-left:10px">This MariaDB instance has been running for ${esc(lookup.Uptime||0)} seconds.</p><div style="display:flex;gap:8px">${resultGrid([{Traffic:'Received',Bytes:received},{Traffic:'Sent',Bytes:sent},{Traffic:'Total',Bytes:received+sent}])}${resultGrid([{Connections:'Max. concurrent connections',Value:lookup.Max_used_connections||0},{Connections:'Failed attempts',Value:lookup.Aborted_connects||0},{Connections:'Aborted',Value:lookup.Aborted_clients||0},{Connections:'Total',Value:lookup.Connections||0}])}</div>`}
async function usersView(){let rows=[];try{rows=await q('SELECT User, Host FROM mysql.user ORDER BY User, Host')}catch{}content.innerHTML=subTabs(['User accounts overview','User groups'],'User accounts overview')+'<h1 style="margin:20px 28px">User accounts overview</h1>'+resultGrid(rows.map(r=>({'User name':r.User||'Any','Host name':r.Host,Action:'Local embedded account'})))+'<fieldset><legend>New</legend><span class="muted">'+ico('User accounts')+'Add user account (requires a full server)</span></fieldset>'+message('Account administration is unavailable in this embedded MariaDB build: it does not include the mysql.user privilege table. This app connects as the local embedded root user.','info')}
function settingsView(){content.innerHTML=subTabs(['Manage your settings','Features','SQL queries','Navigation panel','Main panel','Export','Import'],sub||'Manage your settings')+`<div class="panels" style="padding:23px 10px"><div>${panel('Import',`<form id="import-settings"><label><input type="radio" name="settings-source" value="file" checked>Import from file</label><div style="margin-left:26px">Browse your computer: <input name="file" type="file" accept=".json"></div><label><input type="radio" name="settings-source" value="local">Import from browser's storage</label><p style="margin-left:26px">Settings will be imported from your browser's local storage.</p><label><input name="merge" type="checkbox">Merge with current configuration</label><p style="margin-top:18px"><button>Go</button></p></form>`)}</div><div>${panel('Export',`<label><input type="radio" name="settings-export" value="json" checked>Save as JSON file</label><br><label><input type="radio" name="settings-export" value="local">Save to browser's storage</label><p style="margin-left:26px">Settings will be saved in your browser's local storage.</p><button data-action="export-settings">Go</button>`)}${panel('Reset',`<p>You can reset all your settings and restore them to default values.</p><button data-action="reset-settings">Reset</button>`)}</div></div>`;if(sub&&sub!=='Manage your settings'){content.innerHTML+=`<fieldset><legend>${esc(sub)}</legend><form id="preferences"><div class="field"><label>Navigation panel width</label><input name="width" type="number" min="180" max="500" value="${parseInt(getComputedStyle(document.documentElement).getPropertyValue('--nav-width'))||240}"></div><div class="field"><label>Number of rows</label><select name="rows">${[25,50,100,250].map(n=>`<option ${rowLimit===n?'selected':''}>${n}</option>`).join('')}</select></div><label><input name="retain" type="checkbox" ${localStorage.getItem('retain-query')==='true'?'checked':''}>Retain query box</label><p><button>Apply</button></p></form></fieldset>`}}
function exportTemplateOptions(){const t=readStoredJSON('export-templates',{});return '<option value="">-- Select a template --</option>'+Object.keys(t).map(n=>`<option>${esc(n)}</option>`).join('')}
function currentExportOptions(){return {format:$('#export-format').value,structure:$('#export-structure').checked,data:$('#export-data').checked,drop:$('#export-drop').checked}}
function applyExportOptions(o){$('#export-format').value=o.format;$('#export-structure').checked=o.structure;$('#export-data').checked=o.data;$('#export-drop').checked=o.drop}
function savePreferences(obj){obj={width:Math.max(180,Math.min(500,Number(obj.width)||240)),rows:[25,50,100,250].includes(Number(obj.rows))?Number(obj.rows):25,retain:!!obj.retain};localStorage.setItem('ui-preferences',JSON.stringify(obj));document.documentElement.style.setProperty('--nav-width',(obj.width||240)+'px');rowLimit=Number(obj.rows)||25;localStorage.setItem('retain-query',String(!!obj.retain))}
let rowLimit=25;savePreferences(readStoredJSON('ui-preferences',{}));
async function extraAction(a,el){switch(a){case'collapse-tree':database='';table='';await renderTree();return true;case'themes':dialog('Theme','<p>The pmahomme theme from phpMyAdmin 5.2.1 is installed.</p>');return true;case'format-sql':formatSQLEditor();return true;case'restore-sql':$('#sql-editor').value=localStorage.getItem('autosaved-sql')||'';updateLines();return true;case'save-template':case'update-template':case'delete-template':{let name=a==='save-template'?$('#export-template-name').value.trim():$('#export-template').value;if(!name)throw Error('Enter or select a template name.');let t=readStoredJSON('export-templates',{});if(a==='delete-template')delete t[name];else t[name]=currentExportOptions();localStorage.setItem('export-templates',JSON.stringify(t));$('#export-template').innerHTML=exportTemplateOptions();return true}case'export-settings':{let p=readStoredJSON('ui-preferences',{});if(document.querySelector('[name=settings-export]:checked').value==='local'){localStorage.setItem('saved-ui-preferences',JSON.stringify(p));notice=message('Settings saved to browser storage.');await render()}else download(JSON.stringify(p,null,2),'phpmyadmin-settings.json','application/json');return true}case'reset-settings':savePreferences({width:240,rows:25,retain:false});notice=message('Settings reset.');await render();return true;case'advanced-sql':view='sql';lastSQL=view==='events'?'CREATE EVENT my_event ON SCHEDULE EVERY 1 DAY DO SELECT 1;':'';await render();return true;case'create-user':view='sql';lastSQL="CREATE USER 'student'@'localhost' IDENTIFIED BY 'choose-a-password';\nGRANT SELECT, INSERT, UPDATE, DELETE ON school.* TO 'student'@'localhost';";await render();return true;case'copyrow':{let r={...browseRows[Number(el.dataset.index)]};columns.filter(c=>c.Extra.includes('auto_increment')).forEach(c=>r[c.Field]=null);editing=null;view='insert';insertView();columns.forEach((c,i)=>{document.querySelector('[name="col-'+i+'"]').value=r[c.Field]??'';document.querySelector('[name="null-'+i+'"]').checked=r[c.Field]===null});tabs();return true}case'print':window.print();return true;case'preview-insert':{const f=$('#insert-row'),fd=new FormData(f);let vals=columns.map((c,i)=>fd.has('null-'+i)?null:fd.get('col-'+i));dialog('Preview SQL','<pre class="query">'+esc('INSERT INTO '+qi(table)+' ('+columns.map(c=>qi(c.Field)).join(',')+') VALUES ('+vals.map(lit).join(',')+');')+'</pre>');return true}case'cancel-import':cancelImport=true;return true}return false}
async function extraSubmit(f,fd){if(f.id==='preferences'){savePreferences({width:Number(fd.get('width')),rows:Number(fd.get('rows')),retain:fd.has('retain')});notice=message('Preferences saved.');await render();return true}if(f.id==='import-settings'){let p;if(fd.get('settings-source')==='local'){p=readStoredJSON('saved-ui-preferences',{})}else{let file=f.querySelector('input[type=file]').files[0];if(!file)throw Error('Choose a JSON file.');p=JSON.parse(await file.text())}if(fd.has('merge'))p={...readStoredJSON('ui-preferences',{}),...p};savePreferences(p);notice=message('Settings imported.');await render();return true}return false}
function splitStatements(sql,delimiter=';'){let statements=[],current='',quote='',lineComment=false,blockComment=false;for(let i=0;i<sql.length;i++){const c=sql[i],n=sql[i+1];if(lineComment){current+=c;if(c==='\n')lineComment=false;continue}if(blockComment){current+=c;if(c==='*'&&n==='/'){current+=n;i++;blockComment=false}continue}if(quote){current+=c;if(c==='\\'&&n){current+=n;i++;continue}if(c===quote){if(n===quote){current+=n;i++}else quote=''}continue}if(c==='"'||c==="'"||c==='`'){quote=c;current+=c;continue}if(c==='-'&&n==='-'&&/\s/.test(sql[i+2]||'')){lineComment=true;current+=c;continue}if(c==='#'){lineComment=true;current+=c;continue}if(c==='/'&&n==='*'){blockComment=true;current+=c;continue}if(sql.slice(i,i+delimiter.length)===delimiter){if(current.trim())statements.push(current.trim());current='';i+=delimiter.length-1;continue}current+=c}if(current.trim())statements.push(current.trim());return statements}
async function executeEditor(){const text=$('#sql-editor').value;localStorage.setItem('autosaved-sql',text);localStorage.setItem('retain-query',String($('#retain-query').checked));const name=$('#bookmark-name').value.trim();if(name&&!favorites.includes(text)){favorites.push(text);localStorage.setItem('sql-favorites',JSON.stringify(favorites))}const bound=$('#bind-params').checked,rollback=$('#rollback-query').checked,fk=$('#foreign-keys').checked,delimiter=$('#sql-delimiter').value||';';if(!bound&&!rollback&&delimiter===';'){await engine.exec('SET FOREIGN_KEY_CHECKS = '+(fk?'1':'0'));await runSQL(text);return}let params=bound?JSON.parse($('#parameter-values').value||'[]'):[];if(!Array.isArray(params))throw Error('Bind values must be a JSON array.');await engine.exec('SET FOREIGN_KEY_CHECKS = '+(fk?'1':'0'));if(rollback)await engine.exec('START TRANSACTION');let results=[];try{for(const stmt of splitStatements(text,delimiter))results.push(await engine.exec(stmt,params));if(rollback)await engine.exec('ROLLBACK');await refresh();await persist();lastSQL=text;history.unshift({sql:text,ok:true,time:new Date().toLocaleTimeString()});view='sql';await render();$('#sql-results').innerHTML=results.map(r=>message(r.fields?r.rows.length+' row(s) returned.':(r.affected||0)+' row(s) affected.')+(r.fields?resultGrid(r.rows,r.fields):'')).join('')+(rollback?message('ROLLBACK executed. MariaDB DDL statements commit implicitly.','info'):'');renderHistory()}catch(e){if(rollback)await engine.exec('ROLLBACK');throw e}}
let cancelImport=false;
let lastImportReport=null;
function importReportHTML(report){
 const summary=(report.canceled?'Import canceled. ':report.stopped?'Import stopped. ':'Import finished. ')+report.succeeded+' statements succeeded; '+report.failed+' failed; '+report.warnings.length+' server warnings; '+report.skipped+' skipped.';
 return '<section class="import-report">'+message(summary,report.failed?'error':'')+report.notices.map(n=>message(n,'info')).join('')+'<p><button data-action="download-import-report">Download import report</button> <a data-view="structure">View database structure</a></p>'+(report.errors.length?'<details open><summary>Failed SQL statements ('+report.errors.length+')</summary>'+report.errors.map(e=>'<div class="message error"><b>Statement '+e.statement+' · starting line '+e.line+'</b><p>'+esc(e.message)+'</p><pre class="query">'+esc(e.sql)+'</pre></div>').join('')+'</details>':'')+(report.warnings.length?'<details><summary>Server warnings ('+report.warnings.length+')</summary>'+report.warnings.map(w=>'<p>Statement '+w.statement+' · '+esc(w.level)+' '+esc(w.code)+': '+esc(w.message)+'</p>').join('')+'</details>':'')+'</section>';
}
async function importFile(){
 if(busy)return;
 const file=$('#import-file').files[0];if(!file)throw Error('Choose an SQL file first.');if(file.size>40*1024*1024)throw Error('Use a file smaller than 40 MiB.');
 const charset=$('#import-charset').value,options={skip:Number($('#import-skip').value)||0,foreignKeys:$('#import-fk').checked,mode:$('#import-mode').value,zero:$('#import-zero').checked,compatibility:$('#import-compat').value,continueOnError:$('#import-continue').checked},partial=$('#partial-import').checked,target=$('#import-target').value.trim();
 let stream=file.stream();if(file.name.toLowerCase().endsWith('.gz'))stream=stream.pipeThrough(new DecompressionStream('gzip'));
 const bytes=await new Response(stream).arrayBuffer();if(bytes.byteLength>40*1024*1024)throw Error('The uncompressed SQL file exceeds 40 MiB.');const sql=new TextDecoder(charset).decode(bytes);
 const destination=resolveImportTarget(sql,{target,selectedDatabase:database,filename:file.name});
 if(destination.name)$('#import-target').value=destination.name;
 cancelImport=false;busy=true;const buttons=[...document.querySelectorAll('#import-sql button')];buttons.forEach(b=>b.disabled=true);
 try{
  if(destination.name){await engine.exec('CREATE DATABASE IF NOT EXISTS '+qi(destination.name));await engine.exec('USE '+qi(destination.name));database=destination.name;table=''}
  lastImportReport=await runSQLImport(engine,sql,{...options,isCanceled:()=>cancelImport&&partial,onProgress:async(r,item,percent)=>{$('#import-progress').innerHTML='<progress max="100" value="'+percent+'" style="width:100%"></progress>'+message('Imported '+r.succeeded+'; failed '+r.failed+'; '+percent+'% processed.','info')+(partial?'<button data-action="cancel-import">Cancel</button>':'')}});
  lastImportReport.filename=file.name;lastImportReport.targetDatabase=destination.name;if(destination.source==='filename')lastImportReport.notices.unshift('Target database “'+destination.name+'” was selected from the filename. Existing tables were kept; SQL errors are reported below.');database=(await q('SELECT DATABASE() db'))[0].db||'';table='';await refresh();await persist();
  view='import';await render();$('#import-progress').innerHTML=importReportHTML(lastImportReport);
 }catch(e){database=(await q('SELECT DATABASE() db'))[0].db||'';await refresh();await persist();throw e}
 finally{busy=false;buttons.forEach(b=>b.disabled=false)}
}

document.addEventListener('change',async e=>{if(e.target.id==='import-file'&&!$('#import-target').value.trim())$('#import-target').placeholder=suggestedImportDatabase(e.target.files?.[0]?.name);if(e.target.id==='bind-params')$('#parameter-values').hidden=!e.target.checked;if(e.target.name==='export-method')$('#custom-export').hidden=e.target.value!=='custom';if(e.target.id==='export-template'){let t=readStoredJSON('export-templates',{});if(t[e.target.value])applyExportOptions(t[e.target.value])}if(e.target.id==='connection-collation'){try{await engine.exec('SET collation_connection = ?',[e.target.value])}catch(err){notice=message(err.message,'error');await render()}}});
