document.addEventListener('click',async e=>{let el=e.target.closest('[data-sub],[data-variable],[data-plugin-type]');if(!el||!engine)return;try{if(el.dataset.sub){sub=el.dataset.sub;await render()}else if(el.dataset.variable){let name=el.dataset.variable;view='sql';lastSQL='SHOW GLOBAL VARIABLES LIKE '+lit(name)+';\n-- SET GLOBAL '+qi(name)+" = 'new_value';";await render()}else if(el.dataset.pluginType){document.querySelectorAll('.plugin-group').forEach(s=>s.hidden=s.dataset.kind!==el.dataset.pluginType)}}catch(err){notice=message(err.message,'error');await render()}});


let pendingTable=null;
function createTableView(){content.innerHTML='<h1>Create table '+esc(pendingTable.name)+'</h1><form id="create-table-columns"><div class="table-wrap"><table class="insert-table"><thead><tr>'+['Name','Type','Length/Values','Default','Null','Index','A_I'].map(c=>'<th>'+c+'</th>').join('')+'</tr></thead><tbody>'+Array.from({length:pendingTable.count},(_,i)=>`<tr><td><input name="name-${i}" value="${i===0?'id':''}" required aria-label="Column ${i+1} name"></td><td><select name="type-${i}">${['INT','BIGINT','VARCHAR','TEXT','DECIMAL','FLOAT','DOUBLE','DATE','DATETIME','TIMESTAMP','BOOLEAN','JSON','BLOB'].map(t=>`<option ${i===0&&t==='INT'||i>0&&t==='VARCHAR'?'selected':''}>${t}</option>`).join('')}</select></td><td><input name="length-${i}" value="${i===0?'':'255'}" style="width:90px;min-width:90px" aria-label="Column length"></td><td><input name="default-${i}" placeholder="None" aria-label="Column default"></td><td><input type="checkbox" name="null-${i}" ${i>0?'checked':''}></td><td><select name="key-${i}" style="min-width:100px"><option></option><option ${i===0?'selected':''}>PRIMARY</option><option>UNIQUE</option><option>INDEX</option></select></td><td><input type="checkbox" name="ai-${i}" ${i===0?'checked':''}></td></tr>`).join('')+'</tbody></table></div><div class="field"><label>Storage engine:</label><select name="engine"><option>InnoDB</option><option>MEMORY</option><option>MyISAM</option></select><button>Save</button><button type="button" data-action="preview-table">Preview SQL</button></div></form>'}
function tableDefinition(fd){let names=new Set(),primary=[],indices=[],parts=[];for(let i=0;i<pendingTable.count;i++){let name=String(fd.get('name-'+i)).trim(),type=fd.get('type-'+i),len=String(fd.get('length-'+i)).trim();if(names.has(name))throw Error('Column names must be unique.');names.add(name);if(len&&!/^\d+(,\d+)?$/.test(len))throw Error('Length must be a number or precision,scale.');let def=qi(name)+' '+type+(['VARCHAR','DECIMAL'].includes(type)&&len?'('+len+')':'')+(fd.has('null-'+i)?' NULL':' NOT NULL');let dv=fd.get('default-'+i);if(dv!=='')def+=' DEFAULT '+lit(dv);if(fd.has('ai-'+i))def+=' AUTO_INCREMENT';parts.push(def);let key=fd.get('key-'+i);if(key==='PRIMARY')primary.push(qi(name));if(key==='UNIQUE')indices.push('UNIQUE ('+qi(name)+')');if(key==='INDEX')indices.push('INDEX ('+qi(name)+')')}if(primary.length)parts.push('PRIMARY KEY ('+primary.join(',')+')');return 'CREATE TABLE '+qi(pendingTable.name)+' (\n  '+parts.concat(indices).join(',\n  ')+'\n) ENGINE='+fd.get('engine')+';'}
async function saveInsert(fd){const vals=[],expressions=[];columns.forEach((c,i)=>{let fn=fd.get('fn-'+i),value=fd.has('null-'+i)?null:fd.get('col-'+i);if(['NOW','CURRENT_DATE','UUID'].includes(fn)){expressions.push(fn+'()')}else if(['UPPER','LOWER','MD5','SHA1'].includes(fn)){expressions.push(fn+'(?)');vals.push(value)}else{expressions.push('?');vals.push(value)}});let query;if(editing){let w=rowWhere(editing);query='UPDATE '+qi(table)+' SET '+columns.map((c,i)=>qi(c.Field)+' = '+expressions[i]).join(', ')+' WHERE '+w.sql;vals.push(...w.params)}else query='INSERT INTO '+qi(table)+' ('+columns.map(c=>qi(c.Field)).join(',')+') VALUES ('+expressions.join(',')+')';await engine.exec(query,vals);const after=$('#after-insert').value;editing=null;view=after;notice=message('1 row saved successfully.');await refresh();await persist();await render()}
const baseExtraSubmit=extraSubmit;
extraSubmit=async function(f,fd){if(f.id==='create-table-columns'){await engine.exec(tableDefinition(fd));table=pendingTable.name;pendingTable=null;view='structure';await refresh();await persist();notice=message('Table created successfully.');await render();return true}return baseExtraSubmit(f,fd)};
const baseExtraAction=extraAction;
extraAction=async function(a,el){switch(a){case'download-import-report':if(lastImportReport)download(JSON.stringify(lastImportReport,null,2),'sql-import-report.json','application/json');return true;case'preview-table':dialog('Preview SQL','<pre class="query">'+esc(tableDefinition(new FormData($('#create-table-columns'))))+'</pre>');return true;case'copy-results':await navigator.clipboard.writeText(columns.map(c=>c.Field).join('\t')+'\n'+browseRows.map(r=>columns.map(c=>r[c.Field]??'NULL').join('\t')).join('\n'));return true;case'extra-options':dialog('Extra options','<p>Click a column header to sort. Use Filter rows to search. Use the primary key to edit or delete rows.</p>');return true;case'edit-query':lastSQL='SELECT * FROM '+qi(table)+(activeWhere?' WHERE '+activeWhere:'')+';';view='sql';await render();return true;case'explain-query':lastSQL='EXPLAIN SELECT * FROM '+qi(table)+';';view='sql';await render();await runSQL(lastSQL);return true;case'php-code':dialog('Create PHP code','<pre class="query">'+esc('$sql = "SELECT * FROM '+qi(table)+'";\n$result = mysqli_query($conn, $sql);')+'</pre>');return true;case'create-view':view='sql';lastSQL='CREATE VIEW '+qi(table+'_view')+' AS SELECT * FROM '+qi(table)+';';await render();return true;case'dictionary':dialog('Data dictionary',tables.map(t=>'<p><b>'+esc(t.name)+'</b> — '+esc(t.engine)+' — '+esc(t.collation)+'</p>').join(''));return true;case'bulk-delete':{const ids=[...document.querySelectorAll('.row-check:checked')].map(e=>Number(e.value));if(!ids.length)throw Error('Select rows first.');if(!confirm('Delete '+ids.length+' selected rows?'))return true;for(const i of ids){let w=rowWhere(browseRows[i]);await engine.exec('DELETE FROM '+qi(table)+' WHERE '+w.sql+' LIMIT 1',w.params)}await persist();await browse();return true}case'bulk-copy':{let ids=[...document.querySelectorAll('.row-check:checked')].map(e=>Number(e.value));if(!ids.length)throw Error('Select rows first.');let cols=columns.filter(c=>!c.Extra.includes('auto_increment'));for(const i of ids)await engine.exec('INSERT INTO '+qi(table)+' ('+cols.map(c=>qi(c.Field)).join(',')+') VALUES ('+cols.map(()=>'?').join(',')+')',cols.map(c=>browseRows[i][c.Field]));await persist();await browse();return true}}if(a==='favorites'){let ts=readStoredJSON('favorite-tables',[]);dialog('Favourites',ts.map(t=>'<p>'+esc(t)+'</p>').join('')+(favorites.map((sql,i)=>'<p><a data-favorite="'+i+'">'+esc(sql)+'</a></p>').join('')||'There are no favourite tables or queries.'));return true}return baseExtraAction(a,el)};
document.addEventListener('change',async e=>{try{if(e.target.dataset.checkAll){document.querySelectorAll('.'+e.target.dataset.checkAll).forEach(c=>c.checked=e.target.checked)}if(e.target.id==='browse-limit'){rowLimit=Number(e.target.value);page=0;await browse()}if(e.target.id==='browse-sort'){sort=e.target.value;desc=false;await browse()}if(e.target.id==='show-all-rows'){rowLimit=e.target.checked?10000:25;page=0;await browse()}if(e.target.id==='table-bulk'){let op=e.target.value,selected=[...document.querySelectorAll('.table-check:checked')].map(x=>x.value);if(!selected.length)throw Error('Select tables first.');if(op==='export'){view='export';await render();return}if(!confirm(op+' '+selected.length+' tables?'))return;for(const t of selected)await engine.exec((op==='empty'?'TRUNCATE TABLE ':'DROP TABLE ')+qi(t));await refresh();await persist();await render()}}catch(err){notice=message(err.message,'error');await render()}});
