async function validateEditorSQL(sql){
 if(busy||!sql.trim())return [];
 const delimiter=$('#sql-delimiter')?.value||';';
 if(delimiter!==';')return []; // Routine bodies need their user-selected delimiter.
 const statements=splitStatements(sql,delimiter),diagnostics=[];let offset=0;
 for(const stmt of statements){
  const start=sql.indexOf(stmt,offset);offset=start+stmt.length;
  if(!stmt.replace(/\/\*[\s\S]*?\*\//g,'').replace(/--[^\n]*|#[^\n]*/g,'').trim())continue;
  const name='pma_editor_'+(++editorValidationId);let prepared=false;
  try{await engine.exec('PREPARE '+name+' FROM ?',[stmt]);prepared=true}
  catch(e){const msg=e.message||String(e);if(/not supported in the prepared statement protocol/i.test(msg))continue;
   let at=Math.max(0,start);const near=msg.match(/near '([^']*)'/i);if(near&&near[1]){const n=stmt.indexOf(near[1]);if(n>=0)at+=n}
   diagnostics.push({start:at,end:at+Math.min(15,stmt.length),severity:/syntax|1064/i.test(msg)?'error':'warning',message:msg+(statements.length>1&&!/syntax|1064/i.test(msg)?' (Objects created by earlier statements may not exist yet.)':'')})
  }finally{if(prepared)await engine.exec('DEALLOCATE PREPARE '+name)}
 }
 return diagnostics;
}
